pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Wallet} from "../src/Wallet.sol";

contract InvMutTest is Test {
    Wallet c;
    function setUp() public { c = new Wallet(); }
    function testFuzz_property(uint64 amount, uint64 withdrawAmt, uint64 seed) public {
        vm.assume(amount > 0);
        vm.assume(withdrawAmt > 0);
        vm.assume(amount >= withdrawAmt);
        address caller = address(uint160(uint256(keccak256(abi.encodePacked(seed)))));
        vm.assume(caller != address(0));
        vm.assume(caller != address(c));
        vm.deal(caller, amount);
        vm.prank(caller);
        c.deposit{value: amount}();
        vm.prank(caller);
        c.withdraw(withdrawAmt);
        vm.prank(caller);
        c.refund();
        bool refundOk;
        vm.prank(caller);
        try c.refund() { refundOk = true; } catch { refundOk = false; }
        assertTrue(refundOk);
    }
}
